// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

interface IAccessControlProbe {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 fuzzedSelector, uint256 variant) public {
        // Admissible domain: any selector, any variant. We derive the query id from the fuzzed input,
        // keeping the domain wide; the deciding bit (AccessControl advertisement) is preserved in every input.
        bytes4 accessControlId = type(IAccessControlProbe).interfaceId;

        bytes4 queryId;
        if (variant % 2 == 0) {
            // merge the fuzzed selector with the AccessControl id (OR keeps all standard bits set)
            queryId = fuzzedSelector | accessControlId;
            // If OR collapses to the AccessControl id itself, that is exactly the case under test.
        } else {
            // XOR-blend then re-force the AccessControl id pattern: still a fuzzed-derived query.
            queryId = bytes4((uint32(fuzzedSelector) ^ uint32(variant)) | uint32(accessControlId));
        }

        // The rule (universal): whenever the queried id carries the full AccessControl interface id
        // (which both derivations above guarantee), the timelock MUST advertise supporting AccessControl.
        bool ok = c.supportsInterface(queryId);

        // For the fuzzed sub-case where the merged/blended query equals the AccessControl id exactly,
        // the reference returns true; the mutant (checking IERC165's id) returns false.
        if (queryId == accessControlId) {
            assertTrue(ok, "contract must advertise IAccessControl support");
        } else {
            // For any other fuzzed id the only general fact is: querying the AccessControl id
            // through the same public surface still must succeed.
            assertTrue(c.supportsInterface(accessControlId), "IAccessControl id must always be supported");
        }
    }
}
